mapper.select:
select * from member
member_uuid like concat('%',#{keyword},'%') or name like concat('%',#{keyword},'%')
limit #{skip}, #{size}

mapper.update:
update member
set state = #{state}
where member_uuid = #{member_uuid}

mapper.select:
select * from report
content like concat('%',#{keyword},'%')
order by report_no desc limit #{skip}, #{size}
